CREATE DATABASE IF NOT EXISTS student_portfolio CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE student_portfolio;
CREATE TABLE admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(username));
CREATE TABLE projects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,description TEXT NOT NULL,short_description VARCHAR(255) NOT NULL,technologies VARCHAR(255) NOT NULL,github_url VARCHAR(500) NULL,live_url VARCHAR(500) NULL,image VARCHAR(255) NULL,featured TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(created_at),INDEX(featured));
CREATE TABLE skills (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,category VARCHAR(100) NOT NULL,proficiency TINYINT UNSIGNED NOT NULL,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(proficiency BETWEEN 0 AND 100));
CREATE TABLE contacts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(255) NOT NULL,subject VARCHAR(150) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(email),INDEX(created_at));
